$content = Get-Content "src/features/home/about/about.css" -Raw

$old = ".ab__cred {`n  display: flex;`n  flex-direction: column;`n  align-items: flex-start;`n  gap: 12px;`n  min-width: 0;`n  min-height: 0;`n  color: inherit;`n  text-decoration: none;`n  padding: 0;`n}`n`n/* Standard credential icon (cert, place, community) */`n.ab__cred-mark {`n  display: grid;`n  place-items: center;`n  width: 44px;`n  height: 44px;`n  flex: none;`n  border-radius: 12px;`n  background: #FFFFFF;`n  border: 1px solid var(--line);`n  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.06), 0 1px 1px rgba(0, 0, 0, 0.03);`n}`n`n.ab__cred-mark > img {`n  width: 28px;`n  height: 28px;`n  object-fit: contain;`n}`n`n/* Standardize icon area height for all footer items so titles align */`n.ab__cred .ab__cred-mark {`n  min-height: 50px;`n}`n`n@media (min-width: 1024px) {`n  .ab__cred .ab__cred-mark {`n    min-height: 50px;`n  }`n}`n`n/* WilbertBuildsAI brand logo " + [char]0x2014 + " original transparent PNG with theme-aware switching */`n.ab__cred-logo {`n  display: block;`n  width: 160px;`n  flex: none;`n  /* Height is auto, determined by image aspect ratio */`n  background: transparent;`n  border: none;`n  box-shadow: none;`n  overflow: visible;`n}`n`n@media (min-width: 1024px) {`n  .ab__cred-logo {`n    width: 170px;`n  }`n}`n`n.ab__cred-logo > img {`n  display: block;`n  width: 100%;`n  height: auto;`n  object-fit: contain;`n}`n`n/* Theme-aware logo switching handled by global .only-light / .only-dark rules */"

$new = ".ab__cred {`n  display: grid;`n  grid-template-rows: auto auto;`n  align-items: start;`n  gap: 12px;`n  min-width: 0;`n  min-height: 0;`n  color: inherit;`n  text-decoration: none;`n  padding: 0;`n}`n`n/* Standard credential icon (cert, place, community) */`n.ab__cred-mark {`n  display: grid;`n  place-items: center;`n  width: 44px;`n  height: 44px;`n  flex: none;`n  border-radius: 12px;`n  background: #FFFFFF;`n  border: 1px solid var(--line);`n  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.06), 0 1px 1px rgba(0, 0, 0, 0.03);`n  justify-self: center;`n}`n`n.ab__cred-mark > img {`n  width: 28px;`n  height: 28px;`n  object-fit: contain;`n}`n`n/* WilbertBuildsAI brand logo " + [char]0x2014 + " original transparent PNG with theme-aware switching */`n.ab__cred-logo {`n  display: block;`n  width: 160px;`n  flex: none;`n  /* Height is auto, determined by image aspect ratio */`n  background: transparent;`n  border: none;`n  box-shadow: none;`n  overflow: visible;`n  justify-self: center;`n}`n`n@media (min-width: 1024px) {`n  .ab__cred-logo {`n    width: 170px;`n  }`n}`n`n.ab__cred-logo > img {`n  display: block;`n  width: 100%;`n  height: auto;`n  object-fit: contain;`n}`n`n/* Theme-aware logo switching handled by global .only-light / .only-dark rules */`n`n/* Ensure the logo/icon area has consistent height across all four columns so titles align */`n.ab__cred > :first-child {`n  min-height: 120px;`n  display: grid;`n  place-items: center;`n  width: 100%;`n}"

$content = $content.Replace($old, $new)
Set-Content "src/features/home/about/about.css" $content -NoNewline
Write-Host "Done"